stage(1);q('#agent-consent').checked=true;act('grant');act('inspect');act('expire');act('approve');check('expiry blocks approval',q('.artifact-heading').textContent.includes('Черновик'));act('manual');check('manual UI remains available',q('#crumb').textContent.includes('A /'));check('manual handoff preserves8400',q('.metric').textContent.replace(/\s/g,'')==='8400₽');act('manual-approve');act('manual-export');check('owner can export after agent expiry',blobs.length===3);act('manual-reset');
